def _split_imports(text):
    text = re.sub(r'--[^\n]*', '', text)
    while '/-' in text:
        start = text.index('/-')
        pos = start + 2
        depth = 1
        while depth and pos < len(text):
            if text.startswith('/-', pos):
                depth += 1
                pos += 2
            elif text.startswith('-/', pos):
                depth -= 1
                pos += 2
            else:
