pub fn verify_ticket_conservation(ticket: ClearingTicket) -> bool {
    let recomputed_base: u64 = ticket.net_bps_fee
        + ticket.flash_lp_fee
        + ticket.blob_slot_quotient
        + ticket.calldata_surcharge
        + ticket.prover_levy
